DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_undo u USING (member_id) WHERE md5(b.background_timeline::text) = u.cur_md5) <> 10 THEN
    RAISE EXCEPTION 'a timeline is not the 2026-10-31c value (changed since)';
  END IF;
END $$;

UPDATE public.mp_biography b SET background_timeline = u.tl, background_last_checked = u.checked
  FROM bt_undo u WHERE b.member_id = u.member_id AND md5(b.background_timeline::text) = u.cur_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (4597, 188, 5102, 5129, 420, 4031, 5161, 1587, 4572, 4998) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT sum(jsonb_array_length(background_timeline)) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'rows changed %, outside the 10 %, MPs with a timeline %, entries %', changed, changed_outside, with_timeline, entry_total;
  IF changed <> 10 THEN RAISE EXCEPTION 'expected exactly 10 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 10 changed', changed_outside; END IF;
  IF (SELECT md5(background_timeline::text) FROM public.mp_biography WHERE member_id = 4998) IS DISTINCT FROM 'd5e2e0b632a9bdb5a087d20d3a8a032a' THEN RAISE EXCEPTION '4998 not restored to the export'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (4597, 188, 5102, 5129, 420, 4031, 5161, 1587, 4572) AND (background_timeline IS NOT NULL OR background_last_checked IS NOT NULL)) THEN RAISE EXCEPTION 'a batch 3 row still has a timeline'; END IF;
  IF with_timeline <> 20 THEN RAISE EXCEPTION 'expected 20 MPs with a timeline, got %', with_timeline; END IF;
  IF entry_total <> 236 THEN RAISE EXCEPTION 'expected 236 entries, got %', entry_total; END IF;
END $$;

COMMIT;
